solution.solution.cpp:
#include <cstddef>

class IntArray
{
public:
    explicit IntArray(std::size_t size) : m_data{ new int[size]{} }, m_size{ size } {}

    ~IntArray() { delete[] m_data; }

    IntArray(const IntArray& other) : m_data{ new int[other.m_size] }, m_size{ other.m_size }
    {
        for (std::size_t i{ 0 }; i < m_size; ++i) m_data[i] = other.m_data[i];
    }

    IntArray& operator=(const IntArray& other)
    {
        if (this != &other)
        {
            int* fresh{ new int[other.m_size] };
            for (std::size_t i{ 0 }; i < other.m_size; ++i) fresh[i] = other.m_data[i];
            delete[] m_data;
            m_data = fresh;
            m_size = other.m_size;
        }
        return *this;
    }

    int& operator[](std::size_t i) { return m_data[i]; }
    const int& operator[](std::size_t i) const { return m_data[i]; }
    std::size_t size() const { return m_size; }

    void resize(std::size_t newSize)
    {
        int* fresh{ new int[newSize]{} };
        const std::size_t keep{ newSize < m_size ? newSize : m_size };
        for (std::size_t i{ 0 }; i < keep; ++i) fresh[i] = m_data[i];
        delete[] m_data;
        m_data = fresh;
        m_size = newSize;
    }

private:
    int* m_data{ nullptr };
    std::size_t m_size{ 0 };
};

unitTests:
TEST("starts as zeros") { const IntArray a{ 4 }; CHECK_EQ(a.size(), 4u); CHECK_EQ(a[0], 0); CHECK_EQ(a[3], 0); }
TEST("copy constructor makes an independent copy") { IntArray a{ 3 }; a[0] = 5; IntArray b{ a }; b[0] = 9; CHECK_EQ(a[0], 5); CHECK_EQ(b[0], 9); CHECK_EQ(b.size(), 3u); }
TEST("copy assignment") { IntArray a{ 2 }; a[1] = 8; IntArray b{ 7 }; b = a; CHECK_EQ(b.size(), 2u); CHECK_EQ(b[1], 8); b[1] = 1; CHECK_EQ(a[1], 8); }
TEST("self-assignment") { IntArray a{ 2 }; a[0] = 6; IntArray& alias{ a }; a = alias; CHECK_EQ(a[0], 6); }
TEST("resize keeps what fits") { IntArray a{ 3 }; a[0] = 1; a[1] = 2; a[2] = 3; a.resize(5); CHECK_EQ(a.size(), 5u); CHECK_EQ(a[2], 3); CHECK_EQ(a[4], 0); a.resize(2); CHECK_EQ(a.size(), 2u); CHECK_EQ(a[1], 2); }
TEST("no leaks anywhere") { CHECK_NO_LEAK(IntArray a{ 10 }; IntArray b{ a }; IntArray c{ 3 }; c = a; c.resize(100); b = c; a.resize(0)); }

